    # Set up ~/.agave/config.json

    # We are saving configurations for the first time so we have to set 
    # "current" and add it to "sessions".
    if "sessions" not in agave_context:
        # No existing sessions, so we just add the current context.
        agave_context["current"] = current_context

        # Create an empty dictionary for "sessions" key.
        agave_context["sessions"] = dict()
        # Save current tenant context.
        agave_context["sessions"][current_context["tenantid"]] = {
            current_context["username"]: {
                current_context["client_name"]: current_context
